import {resumeAnalysis} from './resume-analysis.js';
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function analysisHTML(resume,job){
  const a=resumeAnalysis(resume,job.jd,job.parsedJob);
  if(!a)return `<section class="panel"><h3>Resume analysis</h3><p class="help">${!resume.trim()?'Save a base resume to see keyword matches, an estimated ATS score, and improvement suggestions.':'Read the job description link in Edit details to start this analysis.'}</p></section>`;
  return `<section class="analysis-summary"><span class="eyebrow">RESUME ANALYSIS · BASE RESUME</span><div class="analysis-metrics"><div><span>Keyword match</span><strong>${a.match.score}<small>%</small></strong><p>${a.match.matched.length} of ${a.match.total} unique JD terms</p></div><div><span>Estimated ATS score</span><strong>${a.ats}<small>/100</small></strong><p>Keyword coverage + text readiness</p></div></div><p class="help">Hirizz’s estimate is not an employer ATS result or a prediction of hiring success. Analysis uses your current base resume.</p><details class="method"><summary>How these scores are calculated</summary><p class="help">Keyword match = exact unique JD terms found in your resume ÷ unique JD terms, after filtering common words. ATS estimate = 70% keyword match + 30% text readiness. Text readiness = passed checks ÷ 7. These checks inspect extracted text; they cannot assess Word/PDF layout, columns, tables, or actual ATS parsing.</p></details></section><section class="panel"><h3>What to improve</h3><p class="help">Suggestions use your resume and the job posting. They do not create new capabilities or achievements.</p><ol class="improvement-list">${a.improvements.map(i=>`<li><strong>${esc(i.title)}</strong><p>${esc(i.text)}</p>${i.evidence?i.evidence.map(t=>`<blockquote>${esc(t)}</blockquote>`).join(''):''}</li>`).join('')}</ol></section><section class="panel"><h3>Keyword match breakdown</h3><p class="help">Matched terms show the exact resume lines that support them. Missing terms indicate absent wording, not necessarily absent experience.</p><div class="keyword-controls"><input id="keyword-search" class="search" aria-label="Search keywords" placeholder="Search a keyword…"><select id="keyword-filter" aria-label="Filter keyword matches"><option value="all">All keywords</option><option value="matched">Matched only</option><option value="missing">Missing only</option></select></div><p class="keyword-count help" id="keyword-result-count"></p><div class="keyword-list">${[...a.evidence.map(e=>({term:e.term,lines:e.lines,kind:'matched'})),...a.match.missing.map(term=>({term,lines:[],kind:'missing'}))].map(e=>`<details class="keyword-entry" data-keyword="${esc(e.term)}" data-kind="${e.kind}"><summary><span>${esc(e.term)}</span><span class="chip ${e.kind==='missing'?'missing':''}">${e.kind==='matched'?'Matched':'Missing'}</span></summary>${e.lines.length?e.lines.map(l=>`<blockquote>${esc(l)}</blockquote>`).join(''):'<p class="help">Not found in the base resume. Add this wording only if you can substantiate it from your real experience.</p>'}</details>`).join('')}</div></section>${a.skillMatch.length?`<section class="panel"><h3>Skills mentioned in the posting</h3><div class="chips">${a.skillMatch.map(s=>`<span class="chip ${s.matched?'':'missing'}">${esc(s.skill)} · ${s.matched?'Found':'Not found'}</span>`).join('')}</div></section>`:''}<section class="panel"><h3>Resume text readiness · ${a.readiness}%</h3><p class="help">Simple text checks. This is not document-format validation.</p><ul class="readiness-checks">${a.checks.map(c=>`<li><span class="check-mark ${c.pass?'passed':''}">${c.pass?'✓':'○'}</span>${esc(c.label)}<small>${c.pass?'Detected':'Not detected'}</small></li>`).join('')}</ul></section>`;
}
export function wireAnalysis(root){
  const search=root.querySelector('#keyword-search'),filter=root.querySelector('#keyword-filter');if(!search)return;
  function update(){let count=0;for(const entry of root.querySelectorAll('[data-keyword]')){const show=entry.dataset.keyword.includes(search.value.trim().toLowerCase())&&(filter.value==='all'||entry.dataset.kind===filter.value);entry.hidden=!show;if(show)count++;}root.querySelector('#keyword-result-count').textContent=`${count} keywords shown`;}
  search.oninput=update;filter.onchange=update;update();
}
